(function(){
'use strict';
const app=document.getElementById('app');
const defaults={page:'home',activeCourses:['Administrative Law','Evidence','Business Associations','Legal Profession','Criminal Procedure'],attempts:[],reviews:{},customCards:[],customQuestions:[],documents:[],session:null,issueSession:null,cardFilter:'active',cardShowAll:false,recallCourse:'active',recallIndex:0,recallReveal:false,recallText:'',cardIndex:0,cardReveal:false,practice:{course:'active',source:'both',difficulty:'all',count:10,timed:false,focusWeak:false},issueCourse:'all',aiEndpoint:'',questionNo:1};
let state={...defaults},db=null,toastTimer=null,menuOpen=false,storageStatus='local';let working=false;
const draft={course:'Evidence',paste:'',file:null,title:''};
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',practice:'<path d="M8 3H5a2 2 0 0 0-2 2v15a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V8l-5-5H8z"/><path d="M16 3v5h5M8 13h8M8 17h8"/>',cards:'<rect x="3" y="6" width="15" height="13" rx="2"/><path d="M7 3h12a2 2 0 0 1 2 2v11"/>',recall:'<path d="M9 18h6M10 22h4M15 14c1.2-1 2-2.2 2-4a5 5 0 0 0-10 0c0 1.8.8 3 2 4l1 4h4z"/>',issue:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2M6 4l-2-2M18 4l2-2"/>',courses:'<path d="M4 4.5h16v15H4a2 2 0 0 0 0 4h16M4 4.5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2"/>',materials:'<path d="M12 16V3m0 0L7 8m5-5 5 5"/><path d="M4 16v4h16v-4"/>',analytics:'<path d="M4 20V11m5 9V4m5 16v-7m5 7V7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2 2-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6V21h-3v-.2a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1-2-2 .1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.6-1H5v-3h.2a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1 2-2 .1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6V4h3v.2a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1 2 2-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v3h-.2a1.7 1.7 0 0 0-1.6 1z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',spark:'<path d="m12 2 2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z"/>',shield:'<path d="M12 2 20 6v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/>',chevron:'<path d="m9 18 6-6-6-6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',x:'<path d="M5 5l14 14M19 5 5 19"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',trash:'<path d="M4 7h16M10 4h4m-8 3 1 14h10l1-14M10 11v6m4-6v6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',book:'<path d="M3 5a2 2 0 0 1 2-2h14v18H5a2 2 0 0 1-2-2zm0 14a2 2 0 0 1 2-2h14"/>',back:'<path d="m15 18-6-6 6-6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>'};
function ico(name,size=18){return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.book}</svg>`;}
function esc(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
function pct(n,d){return d?Math.round(100*n/d):0;}
function stamp(d){return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function localDay(d){const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
function shuffled(xs){const a=[...xs];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const byQ=()=>[...BUILTIN_QUESTIONS,...state.customQuestions];const byC=()=>[...BUILTIN_CARDS,...state.customCards];
const navItems=[{id:'home',name:'Dashboard',icon:'home'},{id:'practice',name:'Multiple Choice',icon:'practice'},{id:'cards',name:'Flashcards',icon:'cards'},{id:'recall',name:'Rule Recall',icon:'recall'},{id:'issue',name:'Issue Spotting',icon:'issue'},{id:'courses',name:'Course Library',icon:'courses'},{id:'materials',name:'My Materials',icon:'materials'},{id:'analytics',name:'Mastery & Analytics',icon:'analytics'},{id:'settings',name:'Settings & Backup',icon:'settings'}];
function openDB(){return new Promise(resolve=>{try{const req=indexedDB.open('law-study-hub',1);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains('kv'))d.createObjectStore('kv');if(!d.objectStoreNames.contains('documents'))d.createObjectStore('documents',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);}catch(e){resolve(null);}});}
function docFallback(){try{return JSON.parse(localStorage.getItem('law-study-hub-docs')||'{}');}catch{return {};}}
function dbRead(store,key){return new Promise(resolve=>{if(!db)return resolve(store==='documents'?(docFallback()[key]||null):null);try{const tx=db.transaction(store,'readonly');const req=tx.objectStore(store).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null);}catch(e){resolve(null);}});}
function dbAll(store){return new Promise(resolve=>{if(!db)return resolve(store==='documents'?Object.values(docFallback()):[]);try{const req=db.transaction(store,'readonly').objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>resolve([]);}catch(e){resolve([]);}});}
function dbPut(store,obj,key){return new Promise((resolve,reject)=>{if(!db){if(store==='documents'){try{const saved=docFallback();saved[obj.id]=obj;localStorage.setItem('law-study-hub-docs',JSON.stringify(saved));resolve(true);}catch(e){reject(new Error('Browser storage is full. Save a backup or reduce document size.'));}}else resolve(false);return;}try{const tx=db.transaction(store,'readwrite');const req=key===undefined?tx.objectStore(store).put(obj):tx.objectStore(store).put(obj,key);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);req.onerror=()=>reject(req.error);}catch(e){reject(e);}});}
function dbDelete(store,key){return new Promise(resolve=>{if(!db){if(store==='documents'){const saved=docFallback();delete saved[key];try{localStorage.setItem('law-study-hub-docs',JSON.stringify(saved));}catch(e){}}return resolve();}try{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>resolve();}catch(e){resolve();}});}
let saving=Promise.resolve();function persist(){const snapshot=JSON.parse(JSON.stringify(state));if(db){saving=saving.catch(()=>{}).then(()=>dbPut('kv',snapshot,'state')).catch(()=>toast('Could not save local data. Export a backup.'));}else{try{localStorage.setItem('law-study-hub-state',JSON.stringify(snapshot));}catch(e){storageStatus='temporary';toast('Local saving is unavailable in this browser. Export a backup.');}}}
async function boot(){db=await openDB();if(!db){try{localStorage.setItem('law-study-storage-test','1');localStorage.removeItem('law-study-storage-test');}catch(e){storageStatus='temporary';}}let previous=null;if(db)previous=await dbRead('kv','state');else{try{previous=JSON.parse(localStorage.getItem('law-study-hub-state')||'null');}catch(e){previous=null;}}if(previous&&typeof previous==='object')state={...defaults,...previous,practice:{...defaults.practice,...(previous.practice||{})}};if(!Array.isArray(state.activeCourses))state.activeCourses=[...defaults.activeCourses];render();}
function go(page){state.page=page;menuOpen=false;if(page==='cards'){state.cardReveal=false;state.cardIndex=0;}if(page==='recall'){state.recallReveal=false;state.recallIndex=0;}persist();render();scrollTo({top:0,behavior:'instant'});}
function stats(){const a=state.attempts.filter(x=>x.kind==='mcq'||x.kind==='issue');const correct=a.filter(x=>x.correct).length;const unique=new Set(state.attempts.map(x=>x.id)).size;const today=localDay(Date.now());const last7=state.attempts.filter(x=>Date.now()-x.at<7*86400000).length;const due=byC().filter(c=>!state.reviews[c.id]||state.reviews[c.id].due<=Date.now()).filter(c=>state.activeCourses.includes(c.course)).length;let streak=0;const days=new Set(state.attempts.map(x=>localDay(x.at)));let cursor=Date.now();if(!days.has(today))cursor-=86400000;while(days.has(localDay(cursor))){streak++;cursor-=86400000;if(streak>1000)break;}return {attempts:a.length,correct,accuracy:pct(correct,a.length),unique,last7,due,streak};}
function coursePerformance(c){const a=state.attempts.filter(x=>x.course===c&&(x.kind==='mcq'||x.kind==='issue'));return{n:a.length,score:pct(a.filter(x=>x.correct).length,a.length)};}
function weakTopics(){const map={};for(const x of state.attempts.filter(x=>x.kind==='mcq'||x.kind==='issue')){const key=x.course+' ∙ '+x.topic;map[key]??={course:x.course,topic:x.topic,n:0,correct:0};map[key].n++;if(x.correct)map[key].correct++;}return Object.values(map).filter(x=>x.n>=2).map(x=>({...x,score:pct(x.correct,x.n)})).sort((a,b)=>a.score-b.score||b.n-a.n);}
function navButton(p){return `<button class="nav-button ${state.page===p.id?'active':''}" data-action="go" data-page="${p.id}">${ico(p.icon)}<span>${p.name}</span>${p.id==='cards'&&stats().due>0?`<span class="nav-chip">${stats().due}</span>`:''}</button>`;}
function shell(content){const pageTitle=navItems.find(x=>x.id===state.page)?.name||'Dashboard';return `<div class="app-shell"><aside class="sidebar ${menuOpen?'open':''}"><div class="brand"><div class="brand-icon">§</div><div class="brand-copy"><b>Law Study Hub</b><small>Nebraska · 2L Edition</small></div></div><div class="nav-group-label">Study workspace</div>${navItems.slice(0,5).map(navButton).join('')}<div class="nav-group-label">Your library</div>${navItems.slice(5,8).map(navButton).join('')}<div class="nav-group-label">Preferences</div>${navItems.slice(8).map(navButton).join('')}<div class="sidebar-footer"><b>Local-first study mode</b><div class="line"><div style="width:${clamp(stats().accuracy,3,100)}%"></div></div>Personal study history stays in this browser. Use backups in Settings.</div></aside><div class="main"><header class="topbar"><div class="btn-row"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${ico('menu')}</button><div class="crumb">Workspace <span style="margin:0 8px;color:#cacdcf">/</span> <strong>${esc(pageTitle)}</strong></div></div><div class="topbar-right"><span class="local-pill"><span class="dot"></span> ${storageStatus==='local'?'Local storage':'Session only'}</span><span class="user-avatar" title="Study profile">2L</span></div></header><main class="workspace">${content}<div class="footer-note">Independent educational study aid · General U.S. legal rules may vary by jurisdiction and evolve over time · Verify with assigned materials and current authority.<br>Not affiliated with or endorsed by the University of Nebraska.</div></main></div></div>`;}
function heading(k,title,sub){return `<div class="eyebrow">${esc(k)}</div><h1 class="page-title">${esc(title)}</h1><p class="page-sub">${esc(sub)}</p>`;}
function statBox(name,value,foot,icon){return `<div class="stat"><div class="stat-top"><span>${esc(name)}</span><span class="stat-icon">${ico(icon)}</span></div><div class="big">${esc(value)}</div><div class="foot">${esc(foot)}</div></div>`;}
function home(){const s=stats(),recent=state.activeCourses.slice(0,5),weak=weakTopics().slice(0,4);return `<div class="hero"><div><div class="eyebrow" style="color:#e1b37f">YOUR PERSONAL STUDY DESK</div><h1>Build legal knowledge<br>that stays with you.</h1><p>Memorize the rules. Recognize the issues. Practice applying the law—without having coursework completed for you.</p><div class="btn-row"><button class="btn btn-light" data-action="go" data-page="practice">Start practice ${ico('arrow',16)}</button><button class="btn" style="color:white;border:1px solid #ffffff44;background:#ffffff10" data-action="go" data-page="cards">Review flashcards</button></div></div><div class="hero-graphic" aria-hidden="true">§</div></div><div class="stats-grid">${statBox('Questions answered',s.attempts,'Practice and issue spotting','practice')}${statBox('Practice accuracy',s.attempts?s.accuracy+'%':'—','Across graded study questions','target')}${statBox('Active subjects',state.activeCourses.length,'Choose courses in the library','courses')}${statBox('Review cards ready',s.due,'New and scheduled flashcards','clock')}</div><div class="grid-2"><section class="panel"><div class="panel-h"><h3>Active subjects</h3><button class="mini-link" data-action="go" data-page="courses">Manage subjects ${ico('chevron',12)}</button></div>${recent.length?recent.map(c=>{const p=coursePerformance(c),num=byQ().filter(q=>q.course===c).length,cardNum=byC().filter(q=>q.course===c).length;return `<div class="item-row"><div class="course-icon">${esc(c.slice(0,1))}</div><div class="item-copy"><b>${esc(c)}</b><small>${num} MCQs · ${cardNum} cards · ${p.n} attempts</small></div><div class="item-right">${p.n?p.score+'%':'New'}<div class="progress-track"><div class="progress-fill" style="width:${p.n?p.score:0}%"></div></div></div></div>`}).join(''):`<div class="empty">No active subjects. Activate some in Course Library.</div>`}<button class="btn btn-outline btn-sm" style="margin-top:17px" data-action="go" data-page="courses">Browse all subjects</button></section><section class="panel"><div class="panel-h"><h3>What to study next</h3><span class="chip chip-red">Adaptive</span></div>${weak.length?weak.map((x,i)=>`<div class="review-row"><div class="symbol">${i+1}</div><div style="flex:1"><div class="name">${esc(x.topic)}</div><div class="desc">${esc(x.course)} · ${x.score}% correct (${x.n} tries)</div></div><span class="chip chip-amber">Review</span></div>`).join(''):`<div class="review-row"><div class="symbol">✦</div><div><div class="name">Build your first mastery profile</div><div class="desc">Finish practice questions to reveal weak topics.</div></div></div><div class="review-row"><div class="symbol">↻</div><div><div class="name">Start with active recall</div><div class="desc">Review cards or attempt an MCQ session.</div></div></div>`}<div class="btn-row" style="margin-top:13px"><button class="btn btn-primary btn-sm" data-action="go" data-page="practice">Practice now ${ico('arrow',14)}</button><button class="btn btn-outline btn-sm" data-action="go" data-page="recall">Rule recall</button></div></section></div><div class="section-heading"><h2>Your study modes</h2><span class="hint">Choose how you want to learn today</span></div><div class="grid-3">${[{id:'practice',icon:'practice',name:'Multiple-choice practice',detail:'Rules, exceptions, factual application, full explanations.'},{id:'cards',icon:'cards',name:'Spaced flashcards',detail:'Memory-based reviews that adjust to your ratings.'},{id:'issue',icon:'issue',name:'Issue spotting',detail:'Identify the doctrines a hypothetical implicates.'},{id:'recall',icon:'recall',name:'Rule recall',detail:'Type key legal tests from memory before revealing.'},{id:'materials',icon:'materials',name:'My study materials',detail:'Make review cards from course notes and readings.'},{id:'analytics',icon:'analytics',name:'Mastery tracking',detail:'Pinpoint weak subjects and measure improvement.'}].map(x=>`<button class="panel" style="text-align:left;cursor:pointer" data-action="go" data-page="${x.id}"><div class="course-icon" style="margin-bottom:14px">${ico(x.icon,19)}</div><div style="font-weight:780;margin-bottom:5px">${x.name}</div><div class="muted small">${x.detail}</div><div style="margin-top:13px;color:var(--red)">${ico('arrow',16)}</div></button>`).join('')}</div><div class="section-heading"><h2>How this hub works</h2></div><div class="notes">${ico('shield')}<span>Study-only by design: no assignment drafting or completed case briefs. Preloaded content is a growing starter bank of foundational U.S. law; it is not a substitute for Nebraska-specific rules, course instructions, or checking current primary authorities. Local storage does not automatically synchronize between devices.</span></div>`;}
function getStudyPool(config){let pool=byQ();if(config.course==='active'){pool=pool.filter(q=>state.activeCourses.includes(q.course));}else if(config.course!=='all'){pool=pool.filter(q=>q.course===config.course);}if(config.source!=='both')pool=pool.filter(q=>config.source==='built'?q.source==='builtin':q.source!=='builtin');if(config.difficulty!=='all')pool=pool.filter(q=>String(q.difficulty)===String(config.difficulty));return pool;}
function makeSession(){let pool=getStudyPool(state.practice);if(!pool.length)return toast('No questions match these filters. Try a different course or source.');const attempts=state.attempts;const weight=q=>{const latest=attempts.filter(x=>x.id===q.id).slice(-3);return (!latest.length?2.2:0.8)+(latest.some(x=>!x.correct)?2.8:0)+(state.practice.focusWeak?(!latest.length?.2:(1-pct(latest.filter(x=>x.correct).length,latest.length)/100)*5):0)+Math.random()*1.5;};pool=pool.map(q=>({q,w:weight(q)})).sort((a,b)=>b.w-a.w).map(x=>x.q);const selected=pool.slice(0,Math.min(Number(state.practice.count),pool.length));state.session={ids:selected.map(x=>x.id),orderings:Object.fromEntries(selected.map(x=>[x.id,shuffled([0,1,2,3])])),index:0,answers:{},started:Date.now(),timed:state.practice.timed,seconds:Math.max(90,selected.length*90),finished:false};persist();render();}
function currentQ(){return byQ().find(q=>q.id===state.session?.ids[state.session?.index]);}
function timerRemaining(){const ss=state.session;if(!ss?.timed)return null;return Math.max(0,ss.seconds-Math.floor((Date.now()-ss.started)/1000));}
function formatSec(s){return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
function practice(){const s=state.session;if(!s)return `${heading('PRACTICE ENGINE','Multiple-choice practice','Practice legal rules and applied reasoning. Every answer includes why each option is right or wrong.')}<div class="two-pane" style="margin-top:26px"><section class="panel sticky-sub"><div class="panel-h"><h3>Build a session</h3><span class="chip">Customizable</span></div><div class="field"><label for="p-course">Subjects</label><select id="p-course" class="select" data-setting="course">${[['active','All active courses'],['all','All available courses'],...ALL_COURSES.map(c=>[c,c])].map(([v,l])=>`<option value="${esc(v)}" ${state.practice.course===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div class="field"><label for="p-source">Question source</label><select id="p-source" class="select" data-setting="source">${[['both','Both libraries'],['built','Preloaded library only'],['uploaded','Uploaded materials only']].map(([v,l])=>`<option value="${v}" ${state.practice.source===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="p-diff">Difficulty</label><select id="p-diff" class="select" data-setting="difficulty">${[['all','All difficulty levels'],['1','1 · Fundamentals'],['2','2 · Application'],['3','3 · Advanced']].map(([v,l])=>`<option value="${v}" ${state.practice.difficulty===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Number of questions</label><div class="seg">${[5,10,20].map(n=>`<button class="${state.practice.count===n?'on':''}" data-action="set-count" data-count="${n}">${n}</button>`).join('')}</div></div><label class="checkbox-row"><input type="checkbox" data-setting="timed" ${state.practice.timed?'checked':''}/> Timed exam mode (90 sec/question)</label><label class="checkbox-row"><input type="checkbox" data-setting="focusWeak" ${state.practice.focusWeak?'checked':''}/> Prioritize concepts I missed</label><hr class="divider"><div class="status-line">${ico('book')} <strong>${getStudyPool(state.practice).length}</strong> questions match your filters</div><button class="btn btn-primary btn-block" style="margin-top:15px" data-action="start-session" ${getStudyPool(state.practice).length?'':'disabled'}>Start session ${ico('arrow',16)}</button></section><section><div class="panel" style="padding:28px"><span class="chip chip-red">How it works</span><h2 style="font:normal 27px Georgia,serif;margin:16px 0 11px">Recall. Decide. Learn.</h2><p class="muted">Questions do not reveal their answers in the stem. Select a choice, receive immediate feedback on <b>every option</b>, then move on.</p><div class="outline-list" style="margin-top:22px"><div class="outline-item"><b>1 · Choose a legal rule</b><div class="small muted">Filter by course, source, and difficulty.</div></div><div class="outline-item"><b>2 · Commit to an answer</b><div class="small muted">Feedback appears only after you choose.</div></div><div class="outline-item"><b>3 · Strengthen weak areas</b><div class="small muted">Review history feeds back into future sessions.</div></div></div></div><div class="notes" style="margin-top:14px">${ico('info')}<span>Built-in questions are educational examples with source references, not a licensed commercial bar-question bank. Some electives currently have introductory-only coverage.</span></div></section></div>`;
const total=s.ids.length,graded=Object.keys(s.answers).length,score=Object.entries(s.answers).filter(([id,answer])=>byQ().find(q=>q.id===id)?.answer===answer).length;if(s.finished){return `${heading('SESSION COMPLETE','Your practice results','Review your score, then target concepts you found difficult.')}<div class="study-center" style="margin-top:25px"><div class="panel" style="text-align:center;padding:36px"><div class="eyebrow">SESSION SCORE</div><div class="result-stat">${score} <span style="color:#9ca3aa;font-size:27px">/ ${total}</span></div><div style="font:normal 24px Georgia,serif;margin-bottom:9px">${pct(score,total)}% correct</div><div class="muted small">${s.timed?'Timed':'Untimed'} · ${total} questions · ${graded} answered</div><div class="btn-row" style="justify-content:center;margin-top:25px"><button class="btn btn-primary" data-action="restart-session">New session</button><button class="btn btn-outline" data-action="go" data-page="analytics">View mastery</button><button class="btn btn-outline" data-action="go" data-page="cards">Review cards</button></div></div><section class="panel" style="margin-top:16px"><div class="panel-h"><h3>Question review</h3></div>${s.ids.map((id,i)=>{const q=byQ().find(q=>q.id===id);if(!q)return'';const ans=s.answers[id];return `<div class="item-row"><span class="chip ${ans===q.answer?'chip-green':'chip-red'}">${ans===q.answer?'Correct':ans===undefined?'Unanswered':'Missed'}</span><div class="item-copy"><b>${i+1}. ${esc(q.stem)}</b><small>${esc(q.course)} · ${esc(q.topic)} · ${esc(q.authority||q.sourceName||'General rule')}</small></div></div>`;}).join('')}</section></div>`;}
const q=currentQ();if(!q)return `<div class="panel">Question not found. <button data-action="restart-session">Restart</button></div>`;const answer=s.answers[q.id],reveal=answer!==undefined,remaining=timerRemaining();return `${heading('ACTIVE STUDY SESSION','Multiple-choice practice',`${total} questions selected · Immediate feedback · Progress saved locally`)}<div class="study-center" style="margin-top:27px"><div class="panel question-card"><div class="question-head"><span class="question-type">${esc(q.course)} · ${esc(q.topic)}</span><span class="chip ${s.timed&&remaining<60?'chip-red':''}">${s.timed?ico('clock',13)+' '+formatSec(remaining):`Question ${s.index+1} of ${total}`}</span></div><div class="qbar"><div style="width:${pct(s.index+1,total)}%"></div></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:15px"><span class="chip">Difficulty ${q.difficulty}</span><span class="chip">${q.source==='builtin'?'Preloaded':'My materials'}</span>${s.timed?`<span class="chip">${s.index+1}/${total}</span>`:''}</div><h2 class="question-text">${esc(q.stem)}</h2><div class="answer-grid">${(s.orderings?.[q.id]||[0,1,2,3]).map((orig,i)=>`<button data-action="answer" data-index="${orig}" class="answer-option ${reveal?(orig===q.answer?'correct':orig===answer?'wrong':''):''}" ${reveal?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span class="answer-text">${esc(q.options[orig])}</span>${reveal&&orig===q.answer?`<span style="margin-left:auto;color:var(--green)">${ico('check',17)}</span>`:''}</button>`).join('')}</div>${reveal?`<div class="feedback-box ${answer===q.answer?'':'incorrect'}"><div class="feedback-title" style="color:${answer===q.answer?'var(--green)':'var(--red)'}">${ico(answer===q.answer?'check':'x',18)} ${answer===q.answer?'Correct answer':'Not quite — review the options'}</div>${(s.orderings?.[q.id]||[0,1,2,3]).map((orig,i)=>`<div class="choice-explain"><b>${String.fromCharCode(65+i)}.</b> ${esc(q.feedback[orig])}</div>`).join('')}${q.authority?`<div class="preview-authority">Source / authority: ${esc(q.authority)}</div>`:''}${q.sourceName?`<div class="preview-authority">Uploaded source: ${esc(q.sourceName)} · Review AI/local generation for accuracy.</div>`:''}</div>`:''}<div class="question-bottom"><span class="small muted">${reveal?'Answer saved to your mastery history.':'Choose one answer to see the explanation.'}</span><div class="btn-row"><button class="btn btn-outline" data-action="end-session">Finish</button><button class="btn btn-primary" data-action="next-question" ${reveal?'':'disabled'}>${s.index+1===total?'View results':'Next question'} ${ico('arrow',15)}</button></div></div></div><div class="tiny muted" style="text-align:center;margin-top:13px">Keyboard shortcuts: <span class="kbd">1</span> – <span class="kbd">4</span> to answer · <span class="kbd">Enter</span> to advance.</div></div>`;}
function answerQuestion(idx){const q=currentQ(),s=state.session;if(!q||!s||s.answers[q.id]!==undefined)return;if(s.timed&&timerRemaining()===0)return finishSession();s.answers[q.id]=idx;state.attempts.push({id:q.id,course:q.course,topic:q.topic,kind:'mcq',correct:idx===q.answer,at:Date.now(),source:q.source});persist();render();}
function finishSession(){if(!state.session)return;state.session.finished=true;persist();render();}
function cardsForSelection(v=state.cardFilter){let pool=byC();if(v==='active')return pool.filter(c=>state.activeCourses.includes(c.course));if(v==='all')return pool;return pool.filter(c=>c.course===v);}
function startCards(){let pool=cardsForSelection();if(!state.cardShowAll){const due=pool.filter(c=>!state.reviews[c.id]||state.reviews[c.id].due<=Date.now());if(due.length)pool=due;}pool.sort((a,b)=>(state.reviews[a.id]?.due||0)-(state.reviews[b.id]?.due||0));state.cardQueue=shuffled(pool.map(x=>x.id));state.cardIndex=0;state.cardReveal=false;persist();}
function cardsPage(){if(!Array.isArray(state.cardQueue))startCards();const list=cardsForSelection(),due=list.filter(x=>!state.reviews[x.id]||state.reviews[x.id].due<=Date.now()).length,current=byC().find(x=>x.id===state.cardQueue?.[state.cardIndex]);return `${heading('MEMORIZATION STUDIO','Spaced flashcards','Recall definitions, elements, exceptions, and key doctrines before revealing the answer.')}<div class="study-center" style="margin-top:25px"><div class="panel" style="padding:17px 22px;margin-bottom:15px"><div class="search-row"><div style="flex:1;min-width:170px"><label style="font-size:11px;font-weight:750;display:block;margin-bottom:4px">Deck</label><select class="select" data-action-select="card-filter"><option value="active" ${state.cardFilter==='active'?'selected':''}>All active courses</option><option value="all" ${state.cardFilter==='all'?'selected':''}>All courses</option>${ALL_COURSES.map(c=>`<option value="${esc(c)}" ${state.cardFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="btn-row" style="align-items:flex-end;align-self:end"><span class="chip chip-red">${due} due/new</span><button class="btn btn-outline btn-sm" data-action="cards-toggle-all">${state.cardShowAll?'Only due':'All cards'}</button><button class="btn btn-outline btn-sm" data-action="cards-restart">Restart</button></div></div></div>${current?`<div class="question-head" style="padding:6px 4px 13px"><span class="small muted">Card ${state.cardIndex+1} of ${state.cardQueue.length}</span><span class="chip">${esc(current.course)} · ${esc(current.topic)}</span></div><div class="flashcard" role="button" tabindex="0" data-action="flip-card" aria-label="Flip flashcard"><div class="flash-label">${state.cardReveal?'ANSWER':'ACTIVE RECALL · QUESTION'}</div><div class="flash-main">${esc(state.cardReveal?current.back:current.front)}</div><div class="flash-hint">${state.cardReveal?esc(current.authority||current.sourceName||'Self-assess how well you recalled this rule'):'Click or tap to reveal the answer'}</div></div>${state.cardReveal?`<div class="flash-actions"><button class="btn btn-danger" data-action="rate-card" data-rating="again">Again</button><button class="btn btn-outline" data-action="rate-card" data-rating="hard">Hard</button><button class="btn btn-outline" data-action="rate-card" data-rating="good">Good</button><button class="btn btn-primary" data-action="rate-card" data-rating="easy">Easy</button></div><p class="tiny muted" style="text-align:center;margin-top:11px">Self-rate your recall; the next review date adjusts automatically.</p>`:`<div style="text-align:center;margin-top:16px"><button class="btn btn-primary" data-action="flip-card">Reveal answer ${ico('arrow',15)}</button></div>`}`:`<div class="panel empty"><div class="symbol">✓</div><h3>Deck complete</h3><p>You reviewed the available cards in this session. You can restart with the full deck or switch subjects.</p><div class="btn-row" style="justify-content:center"><button class="btn btn-primary" data-action="cards-toggle-all">Study all cards</button><button class="btn btn-outline" data-action="go" data-page="home">Dashboard</button></div></div>`}<div class="notes" style="margin-top:16px">${ico('info')}<span>The spaced repetition algorithm uses your ratings. “Again” schedules another review soon; “Good” and “Easy” increase the interval. Browser data is device-specific.</span></div></div>`;}
function rateCard(rating){const card=byC().find(c=>c.id===state.cardQueue?.[state.cardIndex]);if(!card)return;const prev=state.reviews[card.id]||{ease:2.5,reps:0,interval:0};let ease=prev.ease,reps=prev.reps,interval=prev.interval;
 if(rating==='again'){reps=0;interval=0;ease=Math.max(1.3,ease-.2);}else if(rating==='hard'){reps=Math.max(1,reps);interval=Math.max(1,Math.ceil(interval*1.2));ease=Math.max(1.3,ease-.15);}else if(rating==='good'){reps++;interval=reps===1?1:reps===2?3:Math.max(4,Math.round(interval*ease));}else{reps++;interval=reps===1?3:reps===2?7:Math.round(interval*ease*1.3);ease=Math.min(3,ease+.1);}
 const due=Date.now()+(rating==='again'?10*60*1000:interval*86400000);state.reviews[card.id]={ease,reps,interval,due,last:Date.now(),rating};state.attempts.push({id:card.id,course:card.course,topic:card.topic,kind:'flashcard',correct:rating==='good'||rating==='easy',at:Date.now(),source:card.source});state.cardIndex++;state.cardReveal=false;persist();render();}
function recallCards(){const sel=state.recallCourse;return byC().filter(c=>sel==='all'?true:sel==='active'?state.activeCourses.includes(c.course):c.course===sel);}
function recallPage(){const pool=recallCards();let idx=state.recallIndex;if(idx>=pool.length){idx=0;state.recallIndex=0;}const card=pool[idx];return `${heading('ACTIVE RETRIEVAL','Rule recall trainer','Reproduce the rule yourself, then compare against the reference answer and self-assess.')}<div class="study-center" style="margin-top:24px"><div class="panel"><div class="search-row" style="justify-content:space-between;margin-bottom:22px"><select class="select" style="max-width:300px" data-action-select="recall-filter"><option value="active" ${state.recallCourse==='active'?'selected':''}>Active courses</option><option value="all" ${state.recallCourse==='all'?'selected':''}>All courses</option>${ALL_COURSES.map(c=>`<option value="${esc(c)}" ${state.recallCourse===c?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="chip">${pool.length?idx+1:0} / ${pool.length}</span></div>${card?`<div class="chip chip-red">${esc(card.course)} · ${esc(card.topic)}</div><h2 class="question-text">${esc(card.front)}</h2><div class="field"><label>Your recall (optional, not uploaded)</label><textarea class="textarea" id="recall-answer" placeholder="Type the rule and any important qualifiers you can remember…" rows="5" ${state.recallReveal?'readonly':''}>${esc(state.recallText||'')}</textarea></div>${state.recallReveal?`<div class="reveal"><b>Reference answer</b><p style="margin:8px 0">${esc(card.back)}</p><div class="preview-authority">${esc(card.authority||card.sourceName||'General study rule')}</div></div><div style="margin:19px 0 6px;font-weight:750">How complete was your answer?</div><div class="btn-row"><button class="btn btn-danger" data-action="rate-recall" data-grade="0">Missed it</button><button class="btn btn-outline" data-action="rate-recall" data-grade="1">Partially recalled</button><button class="btn btn-primary" data-action="rate-recall" data-grade="2">Knew it</button></div>`:`<div class="btn-row" style="margin-top:16px"><button class="btn btn-primary" data-action="reveal-recall">Show reference answer</button><button class="btn btn-outline" data-action="skip-recall">Skip</button></div>`}`:`<div class="empty"><h3>No cards for this course</h3><p>Switch courses or generate cards from your uploaded material.</p></div>`}</div><div class="notes" style="margin-top:15px">${ico('info')}<span>This mode deliberately avoids unreliable automatic grading of free-text legal analysis. You compare your response to the rule and choose your own recall rating.</span></div></div>`;}
function gradeRecall(grade){const card=recallCards()[state.recallIndex];if(card){state.attempts.push({id:card.id,course:card.course,topic:card.topic,kind:'recall',correct:grade===2,at:Date.now(),source:card.source});if(grade===0)state.reviews[card.id]={...(state.reviews[card.id]||{}),due:Date.now(),interval:0,ease:2.3,reps:0};}
state.recallIndex++;state.recallReveal=false;state.recallText='';persist();render();}
function getIssuePool(){return ISSUE_BANK.filter(x=>state.issueCourse==='all'||x.course===state.issueCourse);}
function pickIssue(){let pool=getIssuePool();if(!pool.length)return;const seen=state.attempts.filter(x=>x.kind==='issue').map(x=>x.id);const unseen=pool.filter(x=>!seen.includes(x.id));const pick=shuffled(unseen.length?unseen:pool)[0];state.issueSession={id:pick.id,chosen:[],submitted:false};persist();}
function issuePage(){const opts=[['all','All issue-spotting subjects'],...Array.from(new Set(ISSUE_BANK.map(x=>x.course))).map(x=>[x,x])];if(!state.issueSession||!ISSUE_BANK.some(x=>x.id===state.issueSession.id))pickIssue();const cur=ISSUE_BANK.find(x=>x.id===state.issueSession?.id);const session=state.issueSession;if(!cur)return `<div class="panel empty">No issue-spotting problems available.</div>`;const submitted=session.submitted,missed=cur.issues.filter(x=>!session.chosen.includes(x)),extra=session.chosen.filter(x=>!cur.issues.includes(x)),correct=missed.length===0&&extra.length===0;return `${heading('LEGAL APPLICATION','Issue-spotting lab','Read the facts and identify every doctrine implicated. Multiple issues can be correct.')}<div class="study-center" style="margin-top:24px"><div class="panel question-card"><div class="search-row" style="justify-content:space-between"><span class="chip chip-red">Fact pattern</span><select class="select" style="max-width:280px" data-action-select="issue-filter">${opts.map(([v,l])=>`<option value="${esc(v)}" ${state.issueCourse===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div class="question-type" style="margin-top:20px">${esc(cur.course)} · ${esc(cur.topic)}</div><h2 class="question-text">${esc(cur.stem)}</h2><p class="small muted" style="font-weight:700">Which issues should you analyze? Select all that apply.</p><div class="answer-grid">${cur.choices.map((c,i)=>`<label class="answer-option ${submitted?(cur.issues.includes(c)?'correct':session.chosen.includes(c)?'wrong':''):''}" style="align-items:center;cursor:${submitted?'default':'pointer'}"><input type="checkbox" data-issue-option="${i}" ${session.chosen.includes(c)?'checked':''} ${submitted?'disabled':''} style="accent-color:var(--red);width:17px;height:17px;flex-shrink:0"/><span class="answer-text">${esc(c)}</span></label>`).join('')}</div>${submitted?`<div class="feedback-box ${correct?'':'incorrect'}"><div class="feedback-title" style="color:${correct?'var(--green)':'var(--red)'}">${correct?'All issues identified':'Review the missed and extra issues'}</div><div class="small"><b>Expected issues:</b> ${cur.issues.map(esc).join('; ')}</div>${missed.length?`<div class="choice-explain"><b>Missed:</b> ${missed.map(esc).join(', ')}</div>`:''}${extra.length?`<div class="choice-explain"><b>Not raised here:</b> ${extra.map(esc).join(', ')}</div>`:''}<div class="choice-explain">${esc(cur.why)}</div><div class="preview-authority">Authority: ${esc(cur.authority)}</div></div><button class="btn btn-primary" style="margin-top:20px" data-action="next-issue">Another hypothetical ${ico('arrow',15)}</button>`:`<div class="btn-row" style="justify-content:space-between;margin-top:20px"><span class="small muted">${session.chosen.length} issue${session.chosen.length!==1?'s':''} selected</span><button class="btn btn-primary" data-action="submit-issue" ${session.chosen.length?'':'disabled'}>Submit issues</button></div>`}</div></div>`;}
function catalogPage(){const catalog=COURSE_GROUPS.map(g=>({name:g.name,courses:g.courses}));return `${heading('SUBJECT LIBRARY','Your course library','Activate your subjects without needing a semester schedule. Every subject has at least one foundational study question and memory card.')}<div class="search-row" style="margin:25px 0 7px"><input id="course-search" class="input" placeholder="Search courses and electives…" aria-label="Search courses"/><span class="chip">${ALL_COURSES.length} subjects</span><span class="chip chip-green">${state.activeCourses.length} active</span></div><div class="notes" style="margin:16px 0 6px">${ico('info')}<span>Subject selection controls your default mixed-course study sessions. The library is broad, while question depth varies: major subjects have more practice items than specialized electives. Course availability and titles may change each academic year.</span></div>${catalog.map(g=>`<section class="catalog-group"><div class="group-heading"><h3>${esc(g.name)}</h3><span class="badge-num">${g.courses.length} subjects</span></div><div class="course-catalog">${g.courses.map(c=>{const n=byQ().filter(x=>x.course===c).length,k=byC().filter(x=>x.course===c).length,active=state.activeCourses.includes(c);return `<div class="course-tile" data-course-name="${esc(c.toLowerCase())}"><div class="course-name">${esc(c)}</div><div class="course-counts">${n} practice question${n===1?'':'s'} · ${k} card${k===1?'':'s'}</div><div class="tile-bottom"><span class="chip ${active?'chip-green':''}">${active?'Active':'Available'}</span><button class="toggle ${active?'on':''}" aria-label="${active?'Deactivate':'Activate'} ${esc(c)}" aria-pressed="${active}" data-action="toggle-course" data-course="${esc(c)}"></button></div></div>`;}).join('')}</div></section>`).join('')}`;}
function analyticsPage(){const s=stats(),weak=weakTopics(),allCourses=state.activeCourses.length?state.activeCourses:ALL_COURSES.slice(0,8);const last14=Array.from({length:14},(_,i)=>{const when=Date.now()-(13-i)*86400000;return {day:localDay(when),label:new Date(when).toLocaleDateString(undefined,{weekday:'short'}),n:state.attempts.filter(x=>localDay(x.at)===localDay(when)).length};});const max=Math.max(1,...last14.map(x=>x.n));return `${heading('PROGRESS INTELLIGENCE','Mastery & analytics','See what you remember, what needs review, and how your study pattern is changing.')}<div class="stats-grid">${statBox('Graded attempts',s.attempts,'Multiple choice and issues','practice')}${statBox('Overall accuracy',s.attempts?s.accuracy+'%':'—','Not a prediction of exam score','target')}${statBox('Study streak',s.streak+' day'+(s.streak===1?'':'s'),'Consecutive days with practice','clock')}${statBox('Recall sessions',state.attempts.filter(x=>x.kind==='recall'||x.kind==='flashcard').length,'Self-rated retrieval attempts','cards')}</div><div class="grid-2" style="margin-top:17px"><section class="panel"><div class="panel-h"><h3>Performance by subject</h3></div><div class="analytics-bars">${allCourses.map(c=>{const x=coursePerformance(c);return `<div class="analytics-bar-row"><span title="${esc(c)}">${esc(c)}</span><div class="progress-track" style="height:10px"><div class="progress-fill" style="width:${x.score}%;background:${x.n?(x.score>=75?'#36835d':'#b32439'):'#e8e4e0'}"></div></div><span class="muted">${x.n?x.score+'%':'No data'}</span></div>`;}).join('')}</div><p class="tiny muted" style="margin:17px 0 0">Accuracy is based on answered questions and may be influenced by the size of the question pool.</p></section><section class="panel"><div class="panel-h"><h3>Study activity · last 14 days</h3></div><div style="display:flex;align-items:end;gap:7px;height:195px;padding:12px 0 0;border-bottom:1px solid var(--line)">${last14.map(x=>`<div style="flex:1;text-align:center;min-width:0"><div title="${x.n} study attempts on ${x.day}" style="height:${Math.max(3,Math.round(x.n/max*148))}px;background:${x.n?'#b32439':'#e9e7e4'};border-radius:5px 5px 1px 1px;margin-bottom:8px"></div><span class="tiny muted" style="font-size:9px">${x.label.slice(0,1)}</span></div>`).join('')}</div><p class="tiny muted">Each bar counts quiz, issue-spotting, recall, and flashcard attempts.</p></section></div><section class="panel" style="margin-top:17px"><div class="panel-h"><h3>Topics to strengthen</h3><span class="chip chip-red">Prioritized by accuracy</span></div>${weak.length?weak.slice(0,15).map(x=>`<div class="item-row"><div class="item-copy"><b>${esc(x.topic)}</b><small>${esc(x.course)} · ${x.n} graded attempts</small></div><span class="chip ${x.score>=75?'chip-green':'chip-amber'}">${x.score}%</span></div>`).join(''):`<div class="empty" style="padding:20px"><h3>Still learning your strengths</h3><p>Complete a few quizzes and we’ll show the topics where you need more practice.</p><button class="btn btn-primary" data-action="go" data-page="practice">Begin practice</button></div>`}</section>`;}
function materialsPage(){const uploadedQ=state.customQuestions.length,uploadedC=state.customCards.length;return `${heading('PERSONALIZED LEARNING','My course materials','Turn your own notes and readings into retrieval-practice cards and additional questions—not assignment answers.')}<div class="grid-2" style="margin-top:24px"><section class="panel"><div class="panel-h"><h3>Add study material</h3><span class="chip chip-green">Browser-local</span></div><div class="field"><label>Associate with course</label><select class="select" id="doc-course">${ALL_COURSES.map(c=>`<option value="${esc(c)}" ${draft.course===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="file-box">${ico('upload',26)}<b style="display:block;color:var(--ink)">Upload notes or course materials</b><span class="small">PDF, DOCX, TXT, or Markdown; PDFs and DOCX require internet access to load a parsing library.</span><div><input type="file" id="doc-file" accept=".pdf,.docx,.txt,.md,.text"/></div><div class="tiny" id="doc-file-label">${draft.file?esc(draft.file.name):'No file selected'}</div></div><div class="field" style="margin-top:19px"><label>Or paste notes directly</label><input id="doc-title" class="input" placeholder="Title of these notes (optional)" value="${esc(draft.title)}" style="margin-bottom:9px"/><textarea id="doc-paste" class="textarea" rows="6" placeholder="Paste a glossary, lecture notes, legal rules, or course study guide…">${esc(draft.paste)}</textarea></div><div class="notice"><strong>How local generation works:</strong> the app detects term–definition pairs and explicit rule statements, then produces recall cards and, when there are enough distinct terms, multiple-choice questions. This is heuristic, not full AI reasoning. Verify all generated content against the original file.</div><div class="btn-row" style="margin-top:16px"><button class="btn btn-primary" data-action="generate-local" ${working?'disabled':''}>${ico('spark',16)} ${working?'Reading material…':'Generate study content'}</button>${state.aiEndpoint?`<button class="btn btn-outline" data-action="generate-ai">Generate with AI endpoint</button>`:''}</div><p class="tiny muted" style="margin-top:12px">Files and extracted text are saved in your browser; nothing is sent to a server by local generation. Optional AI generation would send the selected document to your configured endpoint.</p></section><section><div class="panel"><div class="panel-h"><h3>Generated study library</h3><span class="chip">${state.documents.length} documents</span></div><div class="stats-grid" style="grid-template-columns:1fr 1fr;margin:0 0 18px"><div class="stat"><div class="stat-top">New questions</div><div class="big">${uploadedQ}</div></div><div class="stat"><div class="stat-top">New cards</div><div class="big">${uploadedC}</div></div></div>${state.documents.length?state.documents.slice().reverse().map(doc=>`<div class="file-meta"><div style="min-width:0"><b style="word-break:break-word">${esc(doc.name)}</b><small>${esc(doc.course)} · ${doc.cards} cards, ${doc.questions} questions · ${stamp(doc.added)}</small></div><div class="btn-row"><button class="btn btn-outline btn-sm" data-action="view-document" data-doc="${esc(doc.id)}" title="View extracted text">${ico('book',14)}</button><button class="btn btn-danger btn-sm" data-action="delete-document" data-doc="${esc(doc.id)}" title="Delete document and its generated cards">${ico('trash',14)}</button></div></div>`).join(''):`<div class="empty" style="padding:22px"><div class="symbol">✦</div><h3>Your personal bank starts here</h3><p>Upload a glossary or paste notes to create your first cards.</p></div>`}</div><div class="notes" style="margin-top:14px">${ico('shield')}<span>Do not upload privileged client or clinic records. Use only material you are authorized to store or send to an optional AI service. Export backups regularly—clearing browser data may delete your library.</span></div></section></div>`;}
function settingsPage(){const s=stats();return `${heading('LOCAL DATA & PREFERENCES','Settings & backup','Keep your practice history safe and control optional online generation.')}<div class="grid-2" style="margin-top:24px"><section class="panel"><div class="panel-h"><h3>Local study data</h3><span class="chip chip-green">On this device</span></div><div class="outline-list"><div class="outline-item"><b>${state.attempts.length} total study attempts</b><div class="small muted">Includes flashcards, rule recall, MCQs, and issue spotting.</div></div><div class="outline-item"><b>${state.documents.length} uploaded documents</b><div class="small muted">Extracted text stored in IndexedDB where available.</div></div><div class="outline-item"><b>${state.customCards.length+state.customQuestions.length} generated study items</b><div class="small muted">Question bank and progress included in exported backup.</div></div></div><div class="btn-row" style="margin-top:17px"><button class="btn btn-primary" data-action="export-data">${ico('download',16)} Export all data</button><label class="btn btn-outline" for="import-backup" style="cursor:pointer">${ico('upload',16)} Import backup</label><input type="file" accept=".json" id="import-backup" style="position:absolute;width:1px;height:1px;opacity:0"/></div><hr class="divider"><button class="btn btn-danger btn-sm" data-action="reset-all">Delete all local study data</button><p class="tiny muted">Backup/restore includes uploaded extracted text when stored in this browser. It does not synchronize between devices by itself.</p></section><section class="panel"><div class="panel-h"><h3>Optional AI question generation</h3><span class="chip">Advanced setup</span></div><p class="small muted">The dashboard already generates simple recall cards locally. For richer questions based on uploaded notes, you can host the optional secure worker included with the project and paste its URL here.</p><div class="field"><label for="ai-endpoint">Your secure generation endpoint URL</label><input class="input" id="ai-endpoint" value="${esc(state.aiEndpoint||'')}" placeholder="https://your-worker.example.workers.dev"/></div><button class="btn btn-outline" data-action="save-ai-endpoint">Save endpoint URL</button><div class="notice" style="margin-top:16px"><b>Privacy:</b> when you intentionally click “Generate with AI,” the selected file’s extracted text is sent to that endpoint. Never put an AI API key inside GitHub Pages, the browser, or these settings. The secure worker keeps secrets server-side and requires a separate access token.</div><hr class="divider"><div class="panel-h"><h3>About this version</h3></div><p class="small muted">Version 0.1 · Independent beta · All study questions are original examples. The repository includes source files, an optional worker example, and GitHub Pages hosting instructions.</p><p class="small muted">Use current federal and state authorities, professor instructions, and assigned materials to verify rules. Uploaded-generated items are suggestions, not expert-reviewed legal questions.</p><a href="https://catalog.unl.edu/law/juris-doctor-jd/" target="_blank" rel="noopener noreferrer" class="small">Nebraska Law academic catalog ↗</a></section></div>`;}
function render(){if(!app)return;let content='';switch(state.page){case'practice':content=practice();break;case'cards':content=cardsPage();break;case'recall':content=recallPage();break;case'issue':content=issuePage();break;case'courses':content=catalogPage();break;case'materials':content=materialsPage();break;case'analytics':content=analyticsPage();break;case'settings':content=settingsPage();break;default:content=home();}app.innerHTML=shell(content);updateTimer();}
function updateTimer(){if(state.page!=='practice'||!state.session||state.session.finished||!state.session.timed)return;const r=timerRemaining();if(r===0){finishSession();toast('Time is up. Your completed answers have been saved.');return;}const el=document.querySelector('.question-head .chip');if(el){el.innerHTML=ico('clock',13)+' '+formatSec(r);el.classList.toggle('chip-red',r<60);}}
setInterval(updateTimer,1000);
function extractTerms(text){const candidates=[];const seen=new Set();const clean=v=>v.replace(/\s+/g,' ').trim().replace(/^[-•*\s]+/,'');const lines=text.replace(/\r/g,'').split(/\n+/).map(clean).filter(Boolean);function add(term,definition,location){term=clean(term).replace(/[.:\s]+$/,'');definition=clean(definition);if(term.length<3||term.length>75||definition.length<18||definition.length>650||/https?:\/\//i.test(term))return;if(/^(page|chapter|section|lecture|class|notes|reading|example|intro|date|today)$/i.test(term))return;const key=term.toLowerCase();if(seen.has(key))return;seen.add(key);candidates.push({term,definition,location});}
 for(let i=0;i<lines.length;i++){
  const line=lines[i];let m=line.match(/^([A-Za-z][\w\s()\/.'-]{2,64}?)\s*[:–—]\s+(.{18,620})$/);if(m)add(m[1],m[2],`line ${i+1}`);
  m=line.match(/^([A-Z][a-zA-Z\s()\/-]{3,64})\s+(is defined as|refers to|means|requires|consists of|is a|is an)\s+(.{18,500})[.]?$/i);if(m)add(m[1],m[2],`line ${i+1}`);
  if(i+1<lines.length&&line.length>=6&&line.length<64&&!/[.:;!?]$/.test(line)&&/^[A-Z0-9]/.test(line)){
   const next=lines[i+1];if(next.length>40&&next.length<420&&/[.!]$/.test(next))add(line,next,`line ${i+2}`);
  }
 }
 // Fallback: turn strongly worded rule sentences into self-recall prompts.
 if(candidates.length<4){const sents=text.replace(/\s+/g,' ').match(/[^.!?]{35,290}[.!?]/g)||[];for(let i=0;i<sents.length&&candidates.length<35;i++){const st=clean(sents[i]);if(!/\b(must|shall|requires?|means|consists?|elements?|defined as|standard|prohibits?|permitted|may not|unless|exception|duty)\b/i.test(st))continue;const key=st.slice(0,42);add('Rule statement '+(candidates.length+1)+' — '+key.slice(0,26)+'…',st,`excerpt ${i+1}`);}}
 return candidates.slice(0,70);
}
function fromText(text,name,course){const concepts=extractTerms(text),cards=[],questions=[];const docId='doc-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);const now=Date.now();concepts.forEach((x,i)=>{cards.push({id:'uc-'+docId+'-'+i,course,topic:x.term.startsWith('Rule statement')?'Rule excerpts':'Uploaded definitions',front:x.term.startsWith('Rule statement')?'Recall the rule from '+x.location+': '+x.term.replace(/^Rule statement \d+ — /,''): `Define or explain: ${x.term}`,back:x.definition,source:'uploaded',sourceName:name,authority:x.location,documentId:docId});});
 const good=concepts.filter(x=>!x.term.startsWith('Rule statement')&&x.definition.length<360);if(good.length>=4){good.slice(0,30).forEach((x,i)=>{const distractors=shuffled(good.filter(y=>y.term!==x.term)).slice(0,3);if(distractors.length<3)return;const opts=shuffled([x,...distractors]);const answer=opts.findIndex(o=>o.term===x.term);questions.push({id:'uq-'+docId+'-'+i,course,topic:'Uploaded definitions',difficulty:1,kind:'mcq',stem:`According to your uploaded notes, which description best matches “${x.term}”?`,options:opts.map(o=>o.definition),answer,feedback:opts.map(o=>o.term===x.term?`Correct: your notes define ${x.term} this way.`:`This description corresponds to ${o.term}, not ${x.term}.`),authority:x.location,source:'uploaded',sourceName:name,documentId:docId});});}
 return {docId,cards,questions,concepts};}
async function parseFile(file){if(!file)return null;if(file.size>18*1024*1024)throw new Error('Please use a file under 18 MB.');const ext=file.name.split('.').pop().toLowerCase();if(['txt','md','text'].includes(ext))return (await file.text()).slice(0,180000);
 if(ext==='pdf'){
  let pdfjs;try{pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.mjs';}catch(e){throw new Error('PDF parser could not load. Connect to the internet or paste extracted text instead.');}
  const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;const chunks=[];for(let n=1;n<=Math.min(pdf.numPages,80);n++){const page=await pdf.getPage(n),content=await page.getTextContent();const rows=[];let row='',prevY=null;for(const item of content.items){const y=item.transform?.[5]||0;if(prevY!==null&&Math.abs(y-prevY)>2.3){if(row.trim())rows.push(row.trim());row='';}row+=(row?' ':'')+item.str;prevY=y;}if(row.trim())rows.push(row.trim());chunks.push(`\n[PAGE ${n}]\n`+rows.join('\n'));}return chunks.join('\n').slice(0,180000);
 }
 if(ext==='docx'){
  if(!window.mammoth)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/mammoth@1.9.0/mammoth.browser.min.js';s.onload=resolve;s.onerror=()=>reject(new Error('DOCX reader could not load. Connect to the internet or paste text.'));document.head.appendChild(s);});
  const result=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return result.value.slice(0,180000);
 }
 throw new Error('Unsupported file type. Use PDF, DOCX, TXT or Markdown.');}
async function generateLocal(){if(working)return;const course=document.getElementById('doc-course')?.value||draft.course;draft.course=course;draft.title=document.getElementById('doc-title')?.value||draft.title;draft.paste=document.getElementById('doc-paste')?.value||draft.paste;const name=draft.file?.name||draft.title||'Pasted study notes';if(!draft.file&&!draft.paste.trim()){toast('Choose a file or paste some notes first.');return;}
 working=true;const b=document.querySelector('[data-action="generate-local"]');if(b){b.disabled=true;b.textContent='Reading material…';}
 try{const text=(draft.file?await parseFile(draft.file):draft.paste).trim();if(text.length<50)throw new Error('Please supply more text to generate useful study questions.');const out=fromText(text,name,course);if(!out.cards.length)throw new Error('No explicit definitions or legal-rule statements were found. Try lecture notes with rules or a term: definition glossary.');state.customCards.push(...out.cards);state.customQuestions.push(...out.questions);state.documents.push({id:out.docId,name,course,added:Date.now(),cards:out.cards.length,questions:out.questions.length});await dbPut('documents',{id:out.docId,name,course,text});persist();draft.file=null;draft.paste='';draft.title='';working=false;render();toast(`Added ${out.cards.length} recall cards and ${out.questions.length} practice questions.`);}
 catch(e){working=false;toast(e?.message||'Could not read these notes.');render();}}
async function generateAI(){if(working)return;const ep=state.aiEndpoint;const file=draft.file;const course=document.getElementById('doc-course')?.value||draft.course;const pasted=document.getElementById('doc-paste')?.value||draft.paste;const title=document.getElementById('doc-title')?.value||draft.title||file?.name||'Pasted study notes';if(!ep){toast('Configure a secure endpoint under Settings first.');return;}if(!file&&!pasted.trim()){toast('Choose a file or paste some notes.');return;}if(!confirm('Send this document’s extracted text to your configured AI endpoint to create study questions? Do not send confidential or privileged materials.'))return;
 const accessToken=prompt('Enter the private access token for your AI study endpoint (not your OpenAI API key). This token is used for this request only:'); if(!accessToken)return;
 working=true;toast('Creating practice material with your configured endpoint…');try{const text=(file?await parseFile(file):pasted).slice(0,48000);const u=new URL(ep);if(u.protocol!=='https:')throw new Error('The generation endpoint must use HTTPS.');const res=await fetch(u.toString(),{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+accessToken},body:JSON.stringify({course,title,text,limit:14})});if(!res.ok)throw new Error('AI endpoint returned HTTP '+res.status);const body=await res.json();if(!Array.isArray(body.questions)&&!Array.isArray(body.cards))throw new Error('Endpoint response lacked questions or cards.');const docId='doc-ai-'+Date.now();const questions=[];for(const [i,item] of (body.questions||[]).slice(0,40).entries()){
  if(!item||typeof item.stem!=='string'||!Array.isArray(item.options)||item.options.length!==4||!item.options.every(x=>typeof x==='string')||!Number.isInteger(item.answer)||item.answer<0||item.answer>3||!Array.isArray(item.feedback)||item.feedback.length!==4||!item.feedback.every(x=>typeof x==='string'))continue;
  questions.push({id:docId+'-q'+i,course,topic:String(item.topic||'Uploaded study notes').slice(0,70),difficulty:clamp(Number(item.difficulty)||2,1,3),stem:item.stem.slice(0,1500),options:item.options.map(x=>x.slice(0,800)),answer:item.answer,feedback:item.feedback.map(x=>x.slice(0,1400)),authority:String(item.sourceQuote||'Check against uploaded source').slice(0,180),source:'uploaded',sourceName:title,documentId:docId,kind:'mcq'});
 }
 const cards=[];for(const [i,item] of (body.cards||[]).slice(0,60).entries()){if(typeof item.front!=='string'||typeof item.back!=='string'||!item.front||!item.back)continue;cards.push({id:docId+'-c'+i,course,topic:String(item.topic||'Uploaded study notes').slice(0,70),front:item.front.slice(0,400),back:item.back.slice(0,800),authority:String(item.sourceQuote||'Check uploaded source').slice(0,180),source:'uploaded',sourceName:title,documentId:docId});}
 if(!questions.length&&!cards.length)throw new Error('Endpoint did not return valid study content.');state.customQuestions.push(...questions);state.customCards.push(...cards);state.documents.push({id:docId,name:title+' (AI study set)',course,added:Date.now(),questions:questions.length,cards:cards.length});await dbPut('documents',{id:docId,name:title,course,text});persist();draft.file=null;draft.paste='';draft.title='';working=false;render();toast(`Generated ${questions.length} AI questions and ${cards.length} recall cards. Review for accuracy.`);
 }catch(e){working=false;render();toast(e?.message||'AI generation failed.');}}
function downloadJson(obj,filename){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function exportData(){const documents=await dbAll('documents');downloadJson({format:'law-study-hub-backup',version:1,exportedAt:new Date().toISOString(),state,documents},'law-study-hub-backup-'+localDay(Date.now())+'.json');toast('Backup downloaded. Keep this file safe.');}
async function importData(file){try{if(!file)return;const raw=JSON.parse(await file.text());if(raw.format!=='law-study-hub-backup'||raw.version!==1||!raw.state||!Array.isArray(raw.state.attempts)||!Array.isArray(raw.state.activeCourses))throw new Error('This is not a valid Law Study Hub backup.');if(!confirm('Restore the backup? This will replace your current browser-local study history. Export your current data first if needed.'))return;state={...defaults,...raw.state,practice:{...defaults.practice,...(raw.state.practice||{})}};for(const doc of (raw.documents||[])){if(doc&&doc.id&&typeof doc.text==='string')await dbPut('documents',doc);}persist();render();toast('Your backup was restored.');}catch(e){toast(e.message||'Could not restore backup.');}}
async function viewDocument(id){const d=await dbRead('documents',id);if(!d){toast('The source text is not stored in this browser.');return;}const blob=new Blob([d.text],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=d.name.replace(/\.[^.]+$/,'')+'-extracted.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
async function removeDocument(id){const doc=state.documents.find(x=>x.id===id);if(!doc||!confirm(`Remove “${doc.name}” and all questions and cards generated from it?`))return;state.documents=state.documents.filter(x=>x.id!==id);state.customQuestions=state.customQuestions.filter(x=>x.documentId!==id);state.customCards=state.customCards.filter(x=>x.documentId!==id);await dbDelete('documents',id);persist();render();toast('Document and generated content removed.');}
async function resetData(){if(!confirm('This will delete all study progress, uploaded material, and custom questions in this browser. This cannot be undone. Export a backup first. Continue?'))return;if(!confirm('Confirm permanent deletion of local data?'))return;for(const d of state.documents)await dbDelete('documents',d.id);state=JSON.parse(JSON.stringify(defaults));persist();render();toast('Local study data cleared.');}
function setCourseActive(c){if(state.activeCourses.includes(c))state.activeCourses=state.activeCourses.filter(x=>x!==c);else state.activeCourses=[...state.activeCourses,c];persist();render();}
const acts={
 'go':el=>go(el.dataset.page),'menu':()=>{menuOpen=!menuOpen;render();},'toggle-course':el=>setCourseActive(el.dataset.course),
 'set-count':el=>{state.practice.count=Number(el.dataset.count);persist();render();},'start-session':()=>makeSession(),
 'answer':el=>answerQuestion(Number(el.dataset.index)),'next-question':()=>{if(!state.session)return;const q=currentQ();if(q&&state.session.answers[q.id]===undefined)return;state.session.index++;if(state.session.index>=state.session.ids.length)finishSession();else{persist();render();}},
 'end-session':()=>finishSession(),'restart-session':()=>{state.session=null;persist();render();},
 'flip-card':()=>{state.cardReveal=!state.cardReveal;persist();render();},'rate-card':el=>rateCard(el.dataset.rating),
 'cards-restart':()=>{startCards();render();},'cards-toggle-all':()=>{state.cardShowAll=!state.cardShowAll;startCards();render();},
 'reveal-recall':()=>{state.recallText=document.getElementById('recall-answer')?.value||'';state.recallReveal=true;persist();render();},
 'skip-recall':()=>{state.recallIndex++;state.recallReveal=false;state.recallText='';persist();render();},'rate-recall':el=>gradeRecall(Number(el.dataset.grade)),
 'submit-issue':()=>{const item=ISSUE_BANK.find(x=>x.id===state.issueSession?.id);if(!item||state.issueSession.submitted||!state.issueSession.chosen.length)return;const got=state.issueSession.chosen;const correct=got.length===item.issues.length&&got.every(x=>item.issues.includes(x));state.issueSession.submitted=true;state.attempts.push({id:item.id,course:item.course,topic:item.topic,kind:'issue',correct,at:Date.now(),source:'builtin'});persist();render();},
 'next-issue':()=>{pickIssue();render();},'generate-local':()=>generateLocal(),'generate-ai':()=>generateAI(),
 'delete-document':el=>removeDocument(el.dataset.doc),'view-document':el=>viewDocument(el.dataset.doc),
 'export-data':()=>exportData(),'reset-all':()=>resetData(),
 'save-ai-endpoint':()=>{const value=document.getElementById('ai-endpoint')?.value.trim()||'';if(value){try{if(new URL(value).protocol!=='https:')throw new Error('HTTPS required');}catch(e){toast('Enter a valid HTTPS endpoint URL.');return;}}state.aiEndpoint=value;persist();render();toast('Endpoint preference saved locally.');}
};
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!app.contains(b))return;const f=acts[b.dataset.action];if(f){e.preventDefault();f(b);}});
app.addEventListener('change',e=>{const t=e.target;if(t.dataset.setting){const k=t.dataset.setting;state.practice[k]=t.type==='checkbox'?t.checked:t.value;persist();render();return;}if(t.dataset.actionSelect){const v=t.value;if(t.dataset.actionSelect==='card-filter'){state.cardFilter=v;startCards();}if(t.dataset.actionSelect==='recall-filter'){state.recallCourse=v;state.recallIndex=0;state.recallText='';state.recallReveal=false;}if(t.dataset.actionSelect==='issue-filter'){state.issueCourse=v;pickIssue();}persist();render();return;}if(t.matches('[data-issue-option]')){const cur=ISSUE_BANK.find(x=>x.id===state.issueSession?.id);if(cur&&!state.issueSession.submitted){const opt=cur.choices[Number(t.dataset.issueOption)];if(t.checked&&!state.issueSession.chosen.includes(opt))state.issueSession.chosen.push(opt);else if(!t.checked)state.issueSession.chosen=state.issueSession.chosen.filter(x=>x!==opt);persist();render();}return;}if(t.id==='doc-file'){draft.file=t.files?.[0]||null;const label=document.getElementById('doc-file-label');if(label)label.textContent=draft.file?.name||'No file selected';return;}if(t.id==='import-backup'){importData(t.files?.[0]);return;}if(t.id==='doc-course'){draft.course=t.value;return;}});
app.addEventListener('input',e=>{const t=e.target;if(t.id==='course-search'){const search=t.value.trim().toLowerCase();document.querySelectorAll('.course-tile').forEach(card=>{card.style.display=card.dataset.courseName.includes(search)?'':'none';});document.querySelectorAll('.catalog-group').forEach(group=>{group.style.display=group.querySelector('.course-tile:not([style*="display: none"])')?'':'none';});}if(t.id==='doc-paste')draft.paste=t.value;if(t.id==='doc-title')draft.title=t.value;if(t.id==='recall-answer')state.recallText=t.value;});
window.addEventListener('keydown',e=>{if(e.target?.matches('input,textarea,select,[contenteditable]'))return;if(state.page==='cards'&&(e.key===' '||e.key==='Enter')){e.preventDefault();state.cardReveal=!state.cardReveal;persist();render();}if(state.page==='practice'&&state.session&&!state.session.finished){if(['1','2','3','4'].includes(e.key)){e.preventDefault();const qq=currentQ();if(qq){const order=state.session.orderings?.[qq.id]||[0,1,2,3];answerQuestion(order[Number(e.key)-1]);}}else if(e.key==='Enter'){e.preventDefault();const q=currentQ();if(q&&state.session.answers[q.id]!==undefined){state.session.index++;if(state.session.index>=state.session.ids.length)finishSession();else{persist();render();}}}}});
boot();
})();
